/*
 * A085151  Numbers generated by the Fibonacci polynomial x^4 + 3x^2 + 1.
 * https://oeis.org/A085151
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = n^4 + 3*n^2 + 1
 * Range:     u8 n <= 3, u16 n <= 15, u32 n <= 33, u64 n <= 33, u128 n <= 33,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    seq_t x = (seq_t)n;
    seq_t xsq = x * x;           /* n^2 */
    seq_t x4  = xsq * xsq;       /* n^4 */
    return x4 + ((seq_t)3 * xsq) + 1;
}
